import{_ as n,o as a,c as t,a2 as r}from"./chunks/framework.DaGSOal_.js";const f=JSON.parse('{"title":"I","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/i.md","filePath":"glossaire-a-z/i.md"}'),i={name:"glossaire-a-z/i.md"};function o(s,e,l,d,c,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="i" tabindex="-1">I <a class="header-anchor" href="#i" aria-label="Permalink to &quot;I&quot;">​</a></h1><h2 id="icarus" tabindex="-1">Icarus <a class="header-anchor" href="#icarus" aria-label="Permalink to &quot;Icarus&quot;">​</a></h2><p>Icarus est une implémentation de référence d’un portefeuille Cardano léger, développée par Input Output.</p><h2 id="ico-initial-coin-offering-fr-offre-initiale-de-jetons" tabindex="-1">ICO (Initial Coin Offering) (fr : Offre initiale de jetons) <a class="header-anchor" href="#ico-initial-coin-offering-fr-offre-initiale-de-jetons" aria-label="Permalink to &quot;ICO (Initial Coin Offering) (fr : Offre initiale de jetons)&quot;">​</a></h2><p>Une méthode de collecte de fonds dans laquelle de nouveaux projets blockchain vendent des jetons à leurs premiers soutiens, généralement pour financer leur développement. Les ICO étaient particulièrement courantes pendant les années de forte activité de 2017 et 2018, lorsque de nombreux projets les utilisaient pour lever des capitaux importants.</p><h2 id="info-action-fr-action-informative" tabindex="-1">Info Action (fr : Action informative) <a class="header-anchor" href="#info-action-fr-action-informative" aria-label="Permalink to &quot;Info Action (fr : Action informative)&quot;">​</a></h2><p>Un type d’action de gouvernance défini par la CIP-1694, qui enregistre le vote de la communauté sur une information sans imposer de changement sur la chaîne.</p><p>→ <a href="https://cips.cardano.org/cip/CIP-1694" target="_blank" rel="noreferrer">CIP-1694 — Spécification officielle de la gouvernance Cardano</a></p><h2 id="incentive-fr-incitation" tabindex="-1">Incentive (fr : Incitation) <a class="header-anchor" href="#incentive-fr-incitation" aria-label="Permalink to &quot;Incentive (fr : Incitation)&quot;">​</a></h2><p>Dans les blockchains, une incitation est une récompense ou un mécanisme conçu pour motiver les participants à agir de manière à soutenir la sécurité et le fonctionnement du réseau. Sur Cardano, les incitations sont principalement fournies sous forme de récompenses de staking, qui encouragent les détenteurs d’ada et les opérateurs de pools de staking à contribuer à la production des blocs et à la décentralisation.</p><p>→ <a href="https://docs.cardano.org/about-cardano/learn/pledging-rewards" target="_blank" rel="noreferrer">Pledging and rewards — Cardano Docs</a></p><h2 id="incentivised-testnet-itn-fr-reseau-de-test-incitatif" tabindex="-1">Incentivised Testnet (ITN) (fr : Réseau de test incitatif) <a class="header-anchor" href="#incentivised-testnet-itn-fr-reseau-de-test-incitatif" aria-label="Permalink to &quot;Incentivised Testnet (ITN) (fr : Réseau de test incitatif)&quot;">​</a></h2><p>Désigne une phase spéciale du développement de Cardano, lancée à la fin de 2019, pour tester le staking et la délégation avant leur déploiement sur le réseau principal. L’ITN a fourni des informations essentielles sur les performances des pools de staking, la distribution des récompenses et la participation de la communauté, qui ont directement contribué à la conception et aux paramètres de l’ère Shelley de Cardano.</p><h2 id="infrastructure-cardano-fr-infrastructure-de-cardano" tabindex="-1">Infrastructure (Cardano) (fr : Infrastructure de Cardano) <a class="header-anchor" href="#infrastructure-cardano-fr-infrastructure-de-cardano" aria-label="Permalink to &quot;Infrastructure (Cardano) (fr : Infrastructure de Cardano)&quot;">​</a></h2><p>L’infrastructure de Cardano désigne les composants techniques et organisationnels fondamentaux qui permettent à la blockchain de fonctionner de manière sécurisée et fiable. Elle comprend le logiciel du nœud Cardano, l’architecture en couches du protocole — réseau, consensus, règlement et scripts — ainsi que le réseau mondial d’opérateurs de pools de staking qui maintiennent la décentralisation et la résilience.</p><h2 id="initial-coin-offering-ico-fr-offre-initiale-de-jetons" tabindex="-1">Initial Coin Offering (ICO) (fr : Offre initiale de jetons) <a class="header-anchor" href="#initial-coin-offering-ico-fr-offre-initiale-de-jetons" aria-label="Permalink to &quot;Initial Coin Offering (ICO) (fr : Offre initiale de jetons)&quot;">​</a></h2><p>Une méthode de collecte de fonds dans laquelle de nouveaux projets blockchain vendent des jetons à leurs premiers soutiens, généralement pour financer leur développement. Les ICO étaient particulièrement courantes pendant les années de forte activité de 2017 et 2018, lorsque de nombreux projets les utilisaient pour lever des capitaux importants.</p><h2 id="initial-tree-offering-ito-fr-offre-initiale-d-arbres" tabindex="-1">Initial Tree Offering (ITO) (fr : Offre initiale d’arbres) <a class="header-anchor" href="#initial-tree-offering-ito-fr-offre-initiale-d-arbres" aria-label="Permalink to &quot;Initial Tree Offering (ITO) (fr : Offre initiale d’arbres)&quot;">​</a></h2><p>L’Initial Tree Offering (ITO) a été introduite sur Cardano dans le cadre de l’initiative Cardano Forest, en collaboration avec veritree. Dans ce modèle, les participants recevaient des jetons fongibles représentant les arbres qu’ils avaient financés. Ces jetons pouvaient ensuite être échangés contre des NFT servant de preuves permanentes, enregistrées sur la chaîne, du don associé à chaque arbre spécifique.</p><h2 id="input-endorsers-fr-approbateurs-d-entrees" tabindex="-1">Input Endorsers (fr : Approbateurs d’entrées) <a class="header-anchor" href="#input-endorsers-fr-approbateurs-d-entrees" aria-label="Permalink to &quot;Input Endorsers (fr : Approbateurs d’entrées)&quot;">​</a></h2><p>Une fonctionnalité d’évolutivité du protocole de consensus de Cardano qui permet de prévalider les transactions avant leur ajout aux blocs. En séparant la validation des transactions de la production des blocs, les Input Endorsers augmentent le débit et améliorent l’efficacité globale du réseau.</p><h2 id="inter-blockchain-communication-protocol-ibc-fr-protocole-de-communication-inter-blockchains" tabindex="-1">Inter-Blockchain Communication Protocol (IBC) (fr : Protocole de communication inter-blockchains) <a class="header-anchor" href="#inter-blockchain-communication-protocol-ibc-fr-protocole-de-communication-inter-blockchains" aria-label="Permalink to &quot;Inter-Blockchain Communication Protocol (IBC) (fr : Protocole de communication inter-blockchains)&quot;">​</a></h2><p>Une norme développée au sein de l’écosystème Cosmos qui permet à différentes blockchains d’échanger des données et des jetons de manière sécurisée. Elle assure l’interopérabilité entre des réseaux indépendants en établissant des canaux de communication sans tiers de confiance. À la mi-2024, Cardano avait intégré IBC au moyen d’une implémentation par chaîne latérale, permettant l’interopérabilité avec les chaînes utilisant Cosmos SDK et les chaînes latérales compatibles avec Ethereum.</p><p>→ <a href="https://cardanofoundation.org/blog/enhancing-connectivity-cosmos-ethereum-cardano" target="_blank" rel="noreferrer">Enhancing connectivity from Cosmos and Ethereum to Cardano — Cardano Foundation</a></p><h2 id="interledger-protocol-ilp-fr-protocole-interledger" tabindex="-1">Interledger Protocol (ILP) (fr : Protocole Interledger) <a class="header-anchor" href="#interledger-protocol-ilp-fr-protocole-interledger" aria-label="Permalink to &quot;Interledger Protocol (ILP) (fr : Protocole Interledger)&quot;">​</a></h2><p>Le protocole Interledger est un protocole ouvert conçu pour permettre des paiements entre différents registres et réseaux, indépendamment de leur technologie sous-jacente. Il achemine les transactions à travers une chaîne de connecteurs, permettant à la valeur de circuler entre blockchains, banques et systèmes de paiement sans nécessiter d’intégration directe. Son intégration à Cardano est prévue.</p><h2 id="interoperability-fr-interoperabilite" tabindex="-1">Interoperability (fr : Interopérabilité) <a class="header-anchor" href="#interoperability-fr-interoperabilite" aria-label="Permalink to &quot;Interoperability (fr : Interopérabilité)&quot;">​</a></h2><p>Désigne la capacité de différents systèmes blockchain à communiquer, à échanger des données et à transférer de la valeur de manière fluide. Dans l’écosystème Cardano, l’interopérabilité constitue un objectif de conception important, poursuivi notamment au moyen de chaînes latérales, de chaînes partenaires et de l’intégration de protocoles inter-chaînes tels qu’IBC et ILP.</p><h2 id="interplanetary-file-system-ipfs-fr-systeme-de-fichiers-interplanetaire" tabindex="-1">InterPlanetary File System (IPFS) (fr : Système de fichiers interplanétaire) <a class="header-anchor" href="#interplanetary-file-system-ipfs-fr-systeme-de-fichiers-interplanetaire" aria-label="Permalink to &quot;InterPlanetary File System (IPFS) (fr : Système de fichiers interplanétaire)&quot;">​</a></h2><p>L’InterPlanetary File System (IPFS) est un protocole décentralisé pair-à-pair permettant de stocker et de partager des fichiers au sein d’un réseau distribué. Au lieu d’utiliser des adresses fondées sur l’emplacement, comme les URL, IPFS identifie les contenus à l’aide de leur empreinte cryptographique, ce qui rend leur récupération plus résiliente et plus résistante aux altérations. Dans l’écosystème Cardano, IPFS est souvent utilisé pour stocker des données hors chaîne liées à des jetons ou à des NFT, ou à des actions de gouvernance, seule l’empreinte du contenu étant enregistrée sur la chaîne.</p><h2 id="ispo-fr-offre-initiale-de-pool-de-staking" tabindex="-1">ISPO (fr : Offre initiale de pool de staking) <a class="header-anchor" href="#ispo-fr-offre-initiale-de-pool-de-staking" aria-label="Permalink to &quot;ISPO (fr : Offre initiale de pool de staking)&quot;">​</a></h2><p>Une méthode de collecte de fonds dans laquelle les soutiens délèguent leurs ada à un pool de staking désigné et reçoivent les jetons du projet à la place des récompenses de staking habituelles. Les participants conservent la garde de leurs ada pendant toute la durée de la délégation.</p>',32)])])}const m=n(i,[["render",o]]);export{f as __pageData,m as default};
